import{U as e,W as t,nt as n,t as r}from"./chunks/framework.DRwsyrlO.js";import"./chunks/assets.DbQFHwAY.js";var i=JSON.parse(`{"title":"科技空岛 · 从一座岛到太空","description":"向虚空获取资源，发展工业与航天研究，亲手建造飞船和固定空间站。体验 PotgCraft 科技空岛的建设与探索。","frontmatter":{"layout":"home","title":"科技空岛 · 从一座岛到太空","description":"向虚空获取资源，发展工业与航天研究，亲手建造飞船和固定空间站。体验 PotgCraft 科技空岛的建设与探索。","hero":{"name":"科技空岛","text":"一座空岛，不必是世界的全部。","tagline":"从虚空中的第一批资源，到自己的工厂、飞船与空间站。把想法搭出来，再看看空岛之外还有什么。","actions":[{"theme":"brand","text":"客户端与加入方式","link":"/skyblock/#join"},{"theme":"alt","text":"查看新手指南","link":"/skyblock/getting-started.html"}]}},"headers":[],"relativePath":"skyblock/index.md","filePath":"skyblock/index.md"}`),a={name:`skyblock/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<section class="portal-section" aria-labelledby="start"><p class="section-kicker">从有限的土地开始</p><h2 id="start">第一批资源，可以从虚空里来。</h2><p class="section-lead">用专用鱼竿向空中抛竿，钓回材料与种源。种下作物、完成任务、提升刷矿能力，把一小片平台慢慢经营成基地。</p><div class="editorial-grid"><div><h3>虚空漂流钓鱼</h3><p>不同等级有独立奖池，基础材料、农业种源与收藏品各有来路。任务芯片让钓鱼与岛屿成长连在一起。</p><a href="./fishing.html">了解漂流钓鱼</a></div><div><h3>资源设施逐步成长</h3><p>五级刷矿机逐步扩展矿物来源。同岛共享、随时间恢复的矿额，让加工效率和成员分工都值得规划。</p><a href="./resources.html#quota">查看资源规则</a></div><div><h3>工厂之外的生活</h3><p>用农夫乐事经营农场和厨房，用建筑工具与装饰方块完善工坊。和朋友分工，把岛建成喜欢的样子。</p><a href="./getting-started.html">从第一座岛开始</a></div></div></section><section class="portal-section campaign-band" aria-labelledby="让零散机器连成生产线"><div class="campaign-copy"><p class="section-kicker">机械 · 化工 · 能源 · 仓储</p><h2 id="让零散机器连成生产线">让零散的机器，<br>成为按你设计运转的工厂。</h2><p>Create（机械动力）的齿轮与传送带，把生产过程铺在眼前；Mekanism（通用机械）的加工、化工与发电体系，则让原料和能源有更多用途。</p><p>用 Ender IO、Pipez 连接设备，再用 AE2（应用能源）的 ME 网络整理库存、安排自动合成。你可以按需要组合系统，把重复的工作逐步交给机器。</p><p>机械动力的电力衔接、Applied Mekanistics 的系统整合，以及 Industrial Foregoing 的农业与资源自动化，也能加入你的方案。</p></div><div class="campaign-quote"><span>今天还在手工搬的材料，</span><strong>明天，就让产线接手。</strong><p>生产与仓储可以并行发展，不必把每个模组依次“通关”。</p></div></section><section class="portal-section" aria-labelledby="flight"><p class="section-kicker">工业成果，连接航天研究</p><h2 id="flight">亲手造出飞船，然后离开它。</h2><p class="section-lead">这里的“它”，是陪你起步的空岛。完成航天资格与相关研究，把工业材料变成驾驶舱、引擎和船体，组装一艘由自己搭建的方块飞船，再驶向太空。</p><figure class="campaign-photo space-photo campaign-feature-photo"><img src="/images/skyblock/ship-flight.png" alt="自造飞船在太空中航行，远处可见天体" width="1920" height="1080" loading="lazy"><figcaption>玩家自造飞船 · 从方块搭建的船体，到实际航行</figcaption></figure><div class="journey-strip" aria-label="航天发展概览"><div><strong>建立工业</strong><p>组织矿料、能源与化工生产。</p></div><div><strong>取得资格</strong><p>屠龙后提交反物质丸，推进个人航天资格与研究。</p></div><div><strong>组装飞船</strong><p>完成研究，准备船体、设备、燃料与航行条件。</p></div><div><strong>探索太空</strong><p>寻找新资源，经营空间站与新的据点。</p></div></div><p class="campaign-note">这只是发展概览，不是每个模组的固定通关顺序。任务前置与航行要求详见 <a href="./spaceflight.html">航天发展指南</a>。</p><div class="departure-notice"><h3>出发前，先和同岛伙伴商量好。</h3><p>成功从空岛迁移到太阳系太空会触发离岛毕业。岛主毕业会注销原岛，影响队友；普通成员会退出岛屿。背包和末影箱可保留，原岛建筑不会自动装船。</p><a href="./graduation.html">阅读毕业规则与出发检查</a></div></section><section class="portal-section campaign-band" aria-labelledby="station"><figure class="campaign-photo space-photo"><img src="/images/skyblock/station-habitat.png" alt="地火一号公共空间站建筑上方的半透明环境范围球罩" width="1600" height="900" loading="lazy"><figcaption>「地火一号」公共空间站 · 白色球罩标识环境范围</figcaption></figure><div class="campaign-copy"><p class="section-kicker">固定空间站 · PotgCraft 定制扩展</p><h2 id="station">空间站，不只是太空里的外壳。</h2><p>放置固定空间站核心，为建筑设置空气、温度和重力区域。想要自由漂浮，还是在地板上行走？用环境设置，为不同区域安排合适的生活方式。</p><p>在 M 星图中管理站点可见性，把工厂、住处和后续建设留在自己的规划里。空间站的环境与地图设置，可以继续按你的建设计划调整。</p><a class="portal-text-link" href="./stations.html">查看空间站核心指南</a></div></section><section class="portal-section" aria-labelledby="station-life"><p class="section-kicker">一次航行之后</p><h2 id="station-life">在空间站碰面，再聊聊下一站。</h2><p class="section-lead">飞船可以停靠，基地可以继续建设。从孤岛上的工厂，到太空里的公共空间，也多了和其他玩家碰面的地方。</p><figure class="campaign-photo space-photo campaign-feature-photo"><img src="/images/skyblock/station-dock.png" alt="地火一号公共空间站实景，建筑外可见两艘飞船" width="1600" height="900" loading="lazy"><figcaption>「地火一号」公共空间站实景</figcaption></figure></section><section class="portal-section campaign-band" aria-labelledby="island-life"><div class="campaign-copy"><p class="section-kicker">机器之外，也有日常</p><h2 id="island-life">工厂里，也能留一块放松的地方。</h2><p>在基地搭一面投影屏幕，和朋友看点视频，或者给设备之间的小空地添些装饰。工业和航天是玩法的一部分，和谁一起玩，也会成为留下来的理由。</p><p>让生产线继续运转，也给一起玩的日子留点别的节目。</p></div><figure class="campaign-photo space-photo"><img src="/images/skyblock/island-life.png" alt="科技空岛基地内的投影屏幕、角色装饰与工业设备" width="1600" height="900" loading="lazy"><figcaption>科技空岛基地实景 · 设备旁的投影屏幕与装饰</figcaption></figure></section><section class="portal-section" aria-labelledby="pace"><p class="section-kicker">把每个阶段，都玩出自己的样子</p><h2 id="pace">不必急着抵达终点。</h2><p class="section-lead">改一段物流，扩一间厂房，为飞船重新安排设备。资源、工业与航天之间经过适配和拓展，值得投入的不只是最后起飞的那一刻，也包括一路上亲手做出的东西。</p></section><section class="portal-section community-panel" aria-labelledby="join"><div><p class="section-kicker">Java 1.21.1 · 模组玩法</p><h2 id="join">准备开始你的空岛生活？</h2><p>科技空岛需要匹配的模组客户端。正式整合包下载、安装要求和具体连接流程仍待补全，请先在现有 QQ 群确认当前发布信息。</p><p>增强生存的推荐包不能代替科技包。已经进入服务器，可以从创建岛屿和任务面板开始。</p></div><div class="portal-actions"><a class="portal-button" href="https://qm.qq.com/q/qcQuFz2AwM" target="_blank" rel="noopener noreferrer">进群了解加入方式</a><a class="portal-text-link" href="./getting-started.html">打开新手指南</a></div></section><section class="portal-section campaign-directory" aria-label="科技空岛玩家资料"><p>游玩中遇到问题，资料放在这里。</p><div class="quick-links"><a href="./resources.html">任务与矿额</a><a href="./fishing-rewards.html">六级钓鱼奖池</a><a href="./spaceflight.html">航天发展</a><a href="./graduation.html">毕业规则</a><a href="./stations.html">空间站核心</a><a href="./commands.html">常用命令</a><a href="../guides/">全部攻略</a></div><p class="campaign-note">两个子服的背包、货币与存档没有已确认的互通。增强生存的天堂维度也不属于本子服。</p></section>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};